ALTER TABLE organizations ADD COLUMN contact_methods TEXT NOT NULL DEFAULT '[]';
UPDATE organizations SET contact_methods=json_array(json_object('type','email','label','电子邮箱','value',substr(contact,8))) WHERE contact LIKE 'mailto:%';
UPDATE organizations SET contact_methods=json_array(json_object('type','phone','label','电话','value',substr(contact,5))) WHERE contact LIKE 'tel:%';
